/**
 * @name JMESPath expression injection
 * @description User-controlled JMESPath expressions flowing to dangerous evaluation functions
 * @kind path-problem
 * @problem.severity high
 * @id py/jmespath-injection
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module JmespathInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for calls to dangerous functions like eval, exec, compile
    exists(CodeExecution ce | sink = ce.getCode()) or
    // Also check for calls to getattr, setattr, etc.
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("eval").getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("exec").getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("compile").getACall() and
      sink = call.getArg(0)
    )
  }
}

module JmespathInjectionFlow = TaintTracking::Global<JmespathInjectionConfig>;
import JmespathInjectionFlow::PathGraph

from JmespathInjectionFlow::PathNode source, JmespathInjectionFlow::PathNode sink
where JmespathInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential JMESPath expression injection from $@.", source.getNode(), "user input"

/**
 * @name JMESPath-specific code injection
 * @description User-controlled JMESPath expressions flowing to dangerous operations
 * @kind path-problem
 * @problem.severity critical
 * @id py/jmespath-code-injection
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module JMESPathInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // User input to JMESPath search function
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("jmespath").getMember("search").getACall() and
      source = call.getArg(0)
    ) or
    // Also consider any remote flow source as potential input
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Dangerous operations: eval, exec, compile
    exists(CodeExecution ce |
      sink = ce.getCode()
    ) or
    // Also check for getattr, setattr, delattr with dynamic names
    exists(DataFlow::CallCfgNode call |
      call = API::builtin(["eval", "exec", "compile", "getattr", "setattr", "delattr"]).getACall() and
      sink = call.getArg(0)
    ) or
    // Import operations with dynamic module names
    exists(DataFlow::CallCfgNode call |
      call = API::builtin(["__import__", "importlib.import_module"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module JMESPathInjectionFlow = TaintTracking::Global<JMESPathInjectionConfig>;
import JMESPathInjectionFlow::PathGraph

from JMESPathInjectionFlow::PathNode source, JMESPathInjectionFlow::PathNode sink
where JMESPathInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Code injection from $@ to dangerous operation.", source.getNode(), "user input"

/**
 * @name Code injection via eval/exec in jmespath
 * @description Using eval or exec with untrusted input can lead to arbitrary code execution
 * @kind path-problem
 * @problem.severity error
 * @id py/code-injection
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CodeInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(CodeExecution ce |
      sink = ce.getCode()
    )
  }
}

module CodeInjectionFlow = TaintTracking::Global<CodeInjectionConfig>;
import CodeInjectionFlow::PathGraph

from CodeInjectionFlow::PathNode source, CodeInjectionFlow::PathNode sink
where CodeInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Code injection from $@.", source.getNode(), "user input"
